CREATE TEMPORARY VIEW search_to_pdp_duration_${grass_region_without_quote} AS
SELECT
    user_id
    ,pre_property.search_args.request_id as request_id
    ,pre_property.item_id as item_id
    ,SUM(page_duration) as search_to_pdp_duration
FROM
    traffic.dwd_view_di__reg_live
WHERE
    grass_region = ${grass_region}
    AND grass_date = ${local_date}
    AND tz_type = 'local'
    AND user_id > 0
    AND os IN ('ios', 'android')
    AND page_type = 'product'
    AND pre_position_code LIKE 'search.%'
    AND pre_property.search_args.scenario_key IN ('PAGE_GLOBAL_SEARCH', 'PAGE_PDP_SEARCH', 'PAGE_PREFILL_SEARCH')
GROUP BY
    1,2,3;

--sql_divide_splitter--

CREATE TEMPORARY VIEW video_mart_traffic_log_${grass_region_without_quote} AS
SELECT
    user_id
    ,GET_JSON_OBJECT((GET_JSON_OBJECT(data, '$.params.sv_source_search_info')),'$.request_id') AS request_id
    ,CAST(GET_JSON_OBJECT(data, '$.params.item_id') AS BIGINT) AS item_id
    ,vv_id
FROM
    video.video_mart_dwd_traffic_log_full_hi
WHERE
    grass_region = ${grass_region}
    AND grass_date = ${local_date}
    AND user_id > 0
    AND page_type = 'video'
    AND target_type = 'video_play_time'
    AND GET_JSON_OBJECT((GET_JSON_OBJECT(data, '$.params.sv_source_search_info')),'$.request_id') IS NOT NULL
    AND GET_JSON_OBJECT(data, '$.params.sv_source_page')='iaa_srp_video_card'
    AND operation = 'action_video'
GROUP BY
    1,2,3,4;

--sql_divide_splitter--

CREATE TEMPORARY VIEW search_to_video_duration_${grass_region_without_quote} AS
SELECT
    a.user_id AS user_id
    ,request_id
    ,item_id
    ,SUM(watch_duration_ntl) as search_to_video_duration
FROM
    video_mart_traffic_log_${grass_region_without_quote} a
JOIN
    video.video_mart_dws_user_watch_time_ntl_1d b
ON
    a.vv_id = b.vv_id
WHERE
    b.grass_region = ${grass_region}
    AND b.grass_date = ${local_date}
    AND b.user_id > 0
GROUP BY
    1,2,3;

--sql_divide_splitter--

CREATE TEMPORARY VIEW livestream_view_link_${grass_region_without_quote} AS
SELECT
    userid AS user_id
    ,event_id
    ,GET_JSON_OBJECT(data, '$.live_scene_parameters.live_in_search.request_id') AS request_id
    ,CAST(GET_JSON_OBJECT(data, '$.live_scene_parameters.live_in_search.itemid') AS BIGINT) AS item_id
FROM
    traffic.shopee_traffic_dwd_view_hi__reg_s1_live
WHERE
    grass_region = ${grass_region}
    AND local_date BETWEEN DATE_SUB(${local_date}, 1) AND ${local_date}
    AND userid > 0
    AND page_type = 'streaming_room'
    AND GET_JSON_OBJECT(data, '$.live_scene_parameters.live_in_search.request_id') IS NOT NULL
    AND GET_JSON_OBJECT(data, '$.from_source') = 'global_search_srp_live_card_entry'
    AND operation = 'view';

--sql_divide_splitter--

CREATE TEMPORARY VIEW search_to_live_duration_${grass_region_without_quote} AS
SELECT
    user_id
    ,request_id
    ,item_id
    ,SUM(CAST(duration_b AS DOUBLE)) * 1000.0  AS search_to_live_duration
FROM
    livestream_view_link_${grass_region_without_quote} a
JOIN
    livestream.ls_mart_dwd_view_streaming_detail_di b
ON
    a.event_id = b.view_event_id
WHERE
    b.grass_region = ${grass_region}
    AND b.grass_date = ${local_date}
GROUP BY
    1,2,3;

--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dwd_sr_data_warehouse_search_to_page_duration
PARTITION (
    grass_region = ${grass_region}
    ,grass_date = ${local_date}
)
SELECT
    COALESCE(a.user_id, b.user_id, c.user_id) AS user_id
    ,COALESCE(a.request_id, b.request_id, c.request_id) AS request_id
    ,COALESCE(a.item_id, b.item_id, c.item_id) AS item_id
    ,search_to_pdp_duration
    ,search_to_video_duration
    ,search_to_live_duration
FROM
    search_to_pdp_duration_${grass_region_without_quote} a
FULL JOIN
    search_to_video_duration_${grass_region_without_quote} b
ON
    a.user_id = b.user_id
    AND a.request_id = b.request_id
    AND a.item_id = b.item_id
FULL JOIN
    search_to_live_duration_${grass_region_without_quote} c
ON
    COALESCE(a.user_id, b.user_id) = c.user_id
    AND COALESCE(a.request_id, b.request_id) = c.request_id
    AND COALESCE(a.item_id, b.item_id) = c.item_id;
